patch:
diff --git a/runtime/nvidia/op_gemm.cuh b/runtime/nvidia/op_gemm.cuh
index ae75cdc7..8891a666 100644
--- a/runtime/nvidia/op_gemm.cuh
+++ b/runtime/nvidia/op_gemm.cuh
@@ -2656,6 +2656,9 @@ __device__ __forceinline__ void gemv_rows_fp8(__nv_bfloat16* __restrict__ C,
 #ifndef PLOW_NV_FP8_DECODE_MMA
 #define PLOW_NV_FP8_DECODE_MMA 0
 #endif
+#ifndef PLOW_NV_FP8_DECODE_MMA_ALL_ROWS
+#define PLOW_NV_FP8_DECODE_MMA_ALL_ROWS 0
+#endif
 #if PLOW_NV_FP8_DECODE_MMA && defined(PLOW_NV_HOPPER) && PLOW_NV_HOPPER
 #include "op_gemv_fp8_mma.cuh"
 #endif
@@ -2676,7 +2679,7 @@ static __device__ void d_gemv_fp8(__nv_bfloat16* __restrict__ C, const __nv_bflo
                            const uint8_t* __restrict__ W, const float* __restrict__ scale,
                            unsigned M, unsigned N, unsigned K, unsigned slice, unsigned nblk) {
 #if PLOW_NV_FP8_DECODE_MMA && defined(PLOW_NV_HOPPER) && PLOW_NV_HOPPER
-    if (M >= 8 && K && !(K % 256) && blockDim.x == 256) {
+    if ((M >= 8 || PLOW_NV_FP8_DECODE_MMA_ALL_ROWS) && M && K && !(K % 256) && blockDim.x == 256) {
         d_gemv_fp8_mma<false>(C, x, W, nullptr, scale, nullptr, M, N, K, 0, slice, nblk);
         return;
     }
@@ -2701,7 +2704,9 @@ static __device__ void d_gemv_fp8(__nv_bfloat16* __restrict__ C, const __nv_bflo
 #endif
     /* The arena stages ONE x row; B>1 decode has M rows, so fall back to the batched global
      * path (same rule as bf16 d_gemv). Without this the fp8 arms silently computed row 0 only. */
-    if (M > 1) { d_gemv_fp8(C, x, W, scale, M, N, K, slice, nblk); return; }
+    if (M > 1 || (PLOW_NV_FP8_DECODE_MMA && PLOW_NV_FP8_DECODE_MMA_ALL_ROWS)) {
+        d_gemv_fp8(C, x, W, scale, M, N, K, slice, nblk); return;
+    }
     /* NOTE: staging x pre-widened to f32 here would remove the per-row __bfloat162float work,
      * but the arena is sized by the EMITTER for K*2 bytes (bf16), so writing K*4 overruns it and
      * faults with CUDA_ERROR_ILLEGAL_ADDRESS. Row-blocking below gets the same saving without
@@ -2848,7 +2853,7 @@ static __device__ void d_gemv_glu_fp8(__nv_bfloat16* __restrict__ C, const __nv_
                                unsigned M, unsigned N, unsigned K, unsigned act, unsigned slice,
                                unsigned nblk) {
 #if PLOW_NV_FP8_DECODE_MMA && defined(PLOW_NV_HOPPER) && PLOW_NV_HOPPER
-    if (M >= 16 && K && !(K % 256) && blockDim.x == 256) {
+    if ((M >= 16 || PLOW_NV_FP8_DECODE_MMA_ALL_ROWS) && M && K && !(K % 256) && blockDim.x == 256) {
         d_gemv_fp8_mma<true>(C, x, Wg, Wu, sg, su, M, N, K, act, slice, nblk);
         return;
     }
@@ -2954,7 +2959,9 @@ static __device__ void d_gemv_glu_fp8(__nv_bfloat16* __restrict__ C, const __nv_
     }
 #endif
     /* B>1: the arena holds one x row only — fall back to the batched global path. */
-    if (M > 1) { d_gemv_glu_fp8(C, x, Wg, Wu, sg, su, M, N, K, act, slice, nblk); return; }
+    if (M > 1 || (PLOW_NV_FP8_DECODE_MMA && PLOW_NV_FP8_DECODE_MMA_ALL_ROWS)) {
+        d_gemv_glu_fp8(C, x, Wg, Wu, sg, su, M, N, K, act, slice, nblk); return;
+    }
     __nv_bfloat16* xs = arena;
     for (unsigned i = threadIdx.x; i < K; i += blockDim.x) xs[i] = x[i];
     __syncthreads();
